// Image shown when a page is shared (Open Graph, X): generated by the server from the logo,
// name, tagline and colours set in the admin (server/routes/og-image.png.ts)
export const SHARE_IMAGE = { path: '/og-image.png', width: 1200, height: 630 } as const

export interface ShareImageSource {
  siteName: string
  tagline: string
  description: string
  metaDescription: string
  primaryColor: string
  accentColor: string
  logoUrl: string | null
  logoOnDarkUrl: string | null
}

// Changes whenever the image would change, so that social networks fetch the new one
export function shareImageVersion(s: ShareImageSource) {
  const input = [s.siteName, shareImageTagline(s), s.primaryColor, s.accentColor, s.logoUrl, s.logoOnDarkUrl, 1].join('|')
  let hash = 0x811c9dc5
  for (let i = 0; i < input.length; i++) hash = Math.imul(hash ^ input.charCodeAt(i), 0x01000193)
  return (hash >>> 0).toString(36)
}

export function shareImageTagline(s: ShareImageSource) {
  return (s.tagline || s.metaDescription || s.description || '').trim()
}
